def RealizesMenger [NeZero n] (κ : ZMod n → ℝ) : Prop :=
  ∃ v : ZMod n → ℂ, IsSimplePolygon v ∧
    ∀ i : ZMod n, signedMengerR2 (v (i - 1)) (v i) (v (i + 1)) = κ i

